package org.telegram.messenger;

/**
 * Resource ids as the release APK compiles them. The shared strings live far beyond the
 * shrunken table (the real crash reported {@code Cancel} as {@code 0x7f0ff63a}), while the
 * ids of this feature's own file survive at the end of the table.
 */
public final class R {
    public static final class string {
        public static final int ServerSwitchAdd = 0x7f0f02c0;
        public static final int ServerSwitchAddTitle = 0x7f0f02c1;
        public static final int ServerSwitchClipboard = 0x7f0f02c2;
        public static final int ServerSwitchError = 0x7f0f02c3;
        public static final int ServerSwitchJsonHint = 0x7f0f02c4;
        public static final int ServerSwitchOfficial = 0x7f0f02c5;
        public static final int ServerSwitchTitle = 0x7f0f02c6;
        public static final int ServerSwitchUnknownError = 0x7f0f02c7;
        public static final int ServerSwitchCancel = 0x7f0f02c8;
        public static final int ServerSwitchOk = 0x7f0f02c9;

        public static final int Cancel = 0x7f0ff63a;
        public static final int OK = 0x7f0ff63b;
    }
}
